  "verdict": "needs-correction",
  "finding_class": "metadata-only",
  "rationale": "The answers are semantically correct, but the national split is materially overstated. Malaysian Malay dictionaries define habuk as dust and also define debu as fine dust, explicitly linking debu with habuk. Thus debu is an accepted Malaysian equivalent, although habuk may remain a useful Malaysian preference. The English cue is aligned, and no false-friend contrast is supported.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "The cue \"dust\" and sense \"fine particles that settle on household surfaces\" are accurate and aligned.",
      "material_risk": false,
      "evidence_refs": [
        "https://dictionary.cambridge.org/dictionary/english/dust"
      ]
    },
    {
      "subject": "Indonesian answer: debu",
      "conclusion": "Debu is a correct Indonesian term for fine dust or powdery particles.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.kemhan.go.id/itjen/wp-content/uploads/2017/04/KAMUS-BESAR-BAHASA-INDONESIA_Mutatis-Mutandis-Hal-1078.pdf"
      ]
    },
    {
      "subject": "Malaysian answer: habuk",
      "conclusion": "Habuk is a correct and well-supported Malaysian Malay term for dry fine particles found on surfaces or in the air.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=371752&keyword=habuk"
      ]
    },
    {
      "subject": "Overlap and national split",
      "conclusion": "The split is materially overstated: Malaysian Malay also accepts debu for dust and explicitly treats it as a synonym or near-equivalent of habuk. The card may present habuk as a Malaysian preference, but not as a uniquely Malaysian common word contrasted with Indonesian debu.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=150348&keyword=Debu+",
        "https://prpm.dbp.gov.my/Cari1?d=371752&keyword=habuk",
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=dust"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "The relation \"different-common-word\" is not adequately supported because the two forms overlap across varieties. A preference-based or shared-synonym relation would be more accurate.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=150348&keyword=Debu+",
        "https://prpm.dbp.gov.my/Cari1?d=371752&keyword=habuk"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No false-friend contrast is present or warranted. Debu and habuk refer to the same dust concept in the relevant usage, rather than creating a misleading cross-variety meaning contrast.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=150348&keyword=Debu+",
        "https://prpm.dbp.gov.my/Cari1?d=371752&keyword=habuk"
      ]
    }
  ]
}
